  console.log(`Fastlønn: id=${fastlonn?.id} name=${fastlonn?.name} number=${fastlonn?.number}`);
  console.log(`Bonus: id=${bonus?.id} name=${bonus?.name} number=${bonus?.number}`);

  // Test 1: salaryType by name
